func (c *WriteupClient) MapCreateBulk(slice any, setFunc func(*WriteupCreate, int)) *WriteupCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &WriteupCreateBulk{err: fmt.Errorf("calling to WriteupClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*WriteupCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &WriteupCreateBulk{config: c.config, builders: builders}
}

