// Hooks returns the client hooks.
func (c *WriteupClient) Hooks() []Hook {
	return c.hooks.Writeup
}

// Interceptors returns the client interceptors.
func (c *WriteupClient) Interceptors() []Interceptor {
	return c.inters.Writeup
}

func (c *WriteupClient) mutate(ctx context.Context, m *WriteupMutation) (Value, error) {
	switch m.Op() {
	case OpCreate:
		return (&WriteupCreate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdate:
		return (&WriteupUpdate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdateOne:
		return (&WriteupUpdateOne{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpDelete, OpDeleteOne:
		return (&WriteupDelete{config: c.config, hooks: c.Hooks(), mutation: m}).Exec(ctx)
	default:
		return nil, fmt.Errorf("ent: unknown Writeup mutation op: %q", m.Op())
	}
}

// hooks and interceptors per client, for fast access.
type (
	hooks struct {
		Activity, AiConfig, Announcement, ApiKey, AttackReport, Challenge,
		ChallengeHint, ChallengeInstance, ChallengeTag, CheckResult, Competition,
		CompetitionChallenge, Conversation, CronJob, DefenseReport, Dict, ErrorLog,
		ExercisePhase, File, FlagSubmission, LoginLog, Message, Notification,
		Objective, Permission, Project, Role, Scenario, ScoreRecord, ScoringRound,
		Setting, Team, TeamMember, TeamRegistration, User, UserPreference, Webhook,
		Writeup []ent.Hook
	}
	inters struct {
		Activity, AiConfig, Announcement, ApiKey, AttackReport, Challenge,
		ChallengeHint, ChallengeInstance, ChallengeTag, CheckResult, Competition,
		CompetitionChallenge, Conversation, CronJob, DefenseReport, Dict, ErrorLog,
		ExercisePhase, File, FlagSubmission, LoginLog, Message, Notification,
		Objective, Permission, Project, Role, Scenario, ScoreRecord, ScoringRound,
		Setting, Team, TeamMember, TeamRegistration, User, UserPreference, Webhook,
		Writeup []ent.Interceptor
	}
)
